66	template<ExternalStreamType E>
67	class ExternalStream : public IExternalStream
68	{
69	public:
70	    ExternalStream() = default;
71	
72	    explicit ExternalStream(cudaStream_t cudaStream)
73	        : m_cudaStream(cudaStream)
74	    {
75	    }
76	
77	    void setCudaStream(cudaStream_t cudaStream, py::object obj)
78	    {
79	        m_cudaStream = cudaStream;
80	        m_wrappedObj = std::move(obj);
81	    }
82	
83	    cudaStream_t handle() const override
84	    {
85	        return m_cudaStream;
86	    }
87	
88	    py::object wrappedObject() const override
89	    {
90	        return m_wrappedObj;
91	    }
92	
93	private:
94	    cudaStream_t m_cudaStream;
95	    py::object   m_wrappedObj;
96	};
