106	template<>
107	struct type_caster<priv::ExternalStream<priv::VOIDP>>
108	{
109	    PYBIND11_TYPE_CASTER(priv::ExternalStream<priv::VOIDP>, const_name("ctypes.c_void_p"));
110	
111	    bool load(handle src, bool)
112	    {
113	        if (std::string strType = util::GetFullyQualifiedName(src); strType != "ctypes.c_void_p")
114	        {
115	            return false;
116	        }
117	
118	        buffer_info info = ::pybind11::cast<buffer>(src).request();
119	
120	        NVCV_ASSERT(info.itemsize == sizeof(void *));
121	
122	        void *data = *reinterpret_cast<void **>(info.ptr);
123	
124	        value.setCudaStream(reinterpret_cast<cudaStream_t>(data), ::pybind11::cast<object>(src));
125	        return true;
126	    }
127	};
128	
129	template<>
130	struct type_caster<priv::ExternalStream<priv::INT>>
131	{
132	    PYBIND11_TYPE_CASTER(priv::ExternalStream<priv::INT>, const_name("int"));
133	
134	    bool load(handle src, bool)
135	    {
136	        try
137	        {
138	            // REVISIT: don't know how to test if a python object
139	            // is convertible to a type without exceptions.
140	            intptr_t data = src.cast<intptr_t>();
141	            value.setCudaStream(reinterpret_cast<cudaStream_t>(data), ::pybind11::cast<object>(src));
142	            return true;
143	        }
144	        catch (...) // NOSONAR: pybind type casters probe conversions by catching failures.
145	        {
146	            return false;
147	        }
148	    }
149	};
