221	std::shared_ptr<Stream> Stream::Create()
222	{
223	    ::cvcudapy::NvtxRange                   nvtxRange("cvcuda.Stream.create");
224	    std::vector<std::shared_ptr<CacheItem>> vcont = Cache::Instance().fetch(Stream::Key{});
225	
226	    // None found?
227	    if (vcont.empty())
228	    {
229	        std::shared_ptr<Stream> stream(new Stream()); // NOSONAR: constructor is private.
230	        Cache::Instance().add(*stream);
231	        return stream;
232	    }
233	    else
234	    {
235	        // Get the first one
236	        return std::static_pointer_cast<Stream>(vcont[0]);
237	    }
238	}
