288	// Returns by value intentionally: returning a reference into m_auxStreams
289	// would be unsafe because a later insertion can trigger a rehash, invalidating
290	// the reference after the mutex is released.
291	cudaStream_t Stream::GetAuxStream()
292	{
293	    // Tolerate hosts with no CUDA device. The wrap-stream-0 ctor calls this
294	    // at module init for cache warm-up; any real consumer of the returned
295	    // handle (cudaStreamWaitEvent / cudaStreamAddCallback) requires a device
296	    // and would have failed regardless. Returning nullptr here lets
297	    // `import cvcuda` succeed on CPU-only build/CI hosts.
298	    int         dev = 0;
299	    cudaError_t err = cudaGetDevice(&dev);
300	    if (err == cudaErrorNoDevice || err == cudaErrorStubLibrary)
301	    {
302	        (void)cudaGetLastError(); // clear sticky error
303	        return nullptr;
304	    }
305	    util::CheckThrow(err);
306	
307	    // Shared lock: concurrent readers when the entry already exists.
308	    {
309	        std::shared_lock lock(m_auxStreamMutex);
310	        auto             it = m_auxStreams.find(dev);
311	        if (it != m_auxStreams.end())
312	            return it->second;
313	    }
314	
315	    // Exclusive lock: serializes the one-time insertion of a new entry.
316	    std::unique_lock lock(m_auxStreamMutex);
317	    auto [it, inserted] = m_auxStreams.try_emplace(dev, nullptr);
318	    if (inserted)
319	    {
320	        cudaStream_t s = nullptr;
321	        util::CheckThrow(cudaStreamCreateWithFlags(&s, cudaStreamNonBlocking));
322	        it->second = s;
323	    }
324	    return it->second;
325	}
326	
327	void Stream::SyncAuxStream()
328	{
329	    ::cvcudapy::NvtxRange nvtxRange("cvcuda.Stream.syncAuxStream");
330	    // Sync aux streams on all devices.
331	    std::shared_lock      lock(m_auxStreamMutex);
332	    int                   savedDev = 0;
333	    util::CheckThrow(cudaGetDevice(&savedDev));
334	
335	    struct DeviceGuard
336	    {
337	        explicit DeviceGuard(int dev_)
338	            : dev(dev_)
339	        {
340	        }
341	
342	        DeviceGuard(const DeviceGuard &)            = delete;
343	        DeviceGuard(DeviceGuard &&)                 = delete;
344	        DeviceGuard &operator=(const DeviceGuard &) = delete;
345	        DeviceGuard &operator=(DeviceGuard &&)      = delete;
346	
347	        ~DeviceGuard()
348	        {
349	            util::CheckLog(cudaSetDevice(dev));
350	        }
351	
352	        int dev;
353	    };
354	
355	    DeviceGuard guard{savedDev};
356	
357	    for (const auto &[dev, auxStream] : m_auxStreams)
358	    {
359	        util::CheckThrow(cudaSetDevice(dev));
360	        util::CheckThrow(cudaStreamSynchronize(auxStream));
361	    }
362	}
363	
364	Stream::~Stream()
365	{
366	    destroy();
367	}
368	
369	void Stream::destroy()
370	{
371	    if (m_owns && m_handle)
372	    {
373	        int savedDev = 0;
374	        util::CheckLog(cudaGetDevice(&savedDev));
375	        util::CheckLog(cudaSetDevice(m_key.deviceId()));
376	        util::CheckLog(cudaStreamSynchronize(m_handle));
377	        util::CheckLog(cudaStreamDestroy(m_handle));
378	        util::CheckLog(cudaSetDevice(savedDev));
379	        m_handle = nullptr;
380	    }
381	    {
382	        std::unique_lock lock(m_auxStreamMutex);
383	        if (decrementInstanceCount() == 0)
384	        {
385	            int savedDev = 0;
386	            util::CheckLog(cudaGetDevice(&savedDev));
387	            for (const auto &[dev, auxStream] : m_auxStreams)
388	            {
389	                util::CheckLog(cudaSetDevice(dev));
390	                util::CheckLog(cudaStreamSynchronize(auxStream));
391	                util::CheckLog(cudaStreamDestroy(auxStream));
392	            }
393	            m_auxStreams.clear();
394	            util::CheckLog(cudaSetDevice(savedDev));
395	        }
396	    }
397	    {
398	        std::lock_guard lock(m_eventMutex);
399	        int             savedDev = 0;
400	        util::CheckLog(cudaGetDevice(&savedDev));
401	        for (const auto &[dev, evt] : m_events)
402	        {
403	            util::CheckLog(cudaSetDevice(dev));
404	            util::CheckLog(cudaEventDestroy(evt));
405	        }
406	        m_events.clear();
407	        util::CheckLog(cudaSetDevice(savedDev));
408	    }
409	}
