457	void Stream::wait_stream(std::shared_ptr<Stream> other)
458	{
459	    ::cvcudapy::NvtxRange nvtxRange("cvcuda.Stream.wait_stream");
460	    if (!other)
461	        throw std::invalid_argument("other is null");
462	
463	    if (other->handle() == m_handle)
464	        return;
465	
466	    py::gil_scoped_release release;
467	    cudaEvent_t            evt = other->getEvent();
468	    util::CheckThrow(cudaEventRecord(evt, other->handle()));
469	    util::CheckThrow(cudaStreamWaitEvent(m_handle, evt, 0));
470	}
471	
472	Stream &Stream::Current()
473	{
474	    auto defStream = StreamStack::Instance().top();
475	    if (!defStream)
476	    {
477	        // Empty stream stack means Stream::Export skipped wrapping the legacy
478	        // default stream — only happens on no-device hosts. Throw a Python-
479	        // visible error rather than NVCV_ASSERT (which would abort()), so
480	        // that introspection tools (pybind11_stubgen, sphinx) can read the
481	        // class without crashing.
482	        throw StreamError("No default cvcuda.Stream available (no CUDA device visible).");
483	    }
484	    return *defStream;
485	}
486	
487	void Stream::activate()
488	{
489	    ::cvcudapy::NvtxRange nvtxRange("cvcuda.Stream.__enter__");
490	    if (m_owns)
491	    {
492	        int curDev = 0;
493	        util::CheckThrow(cudaGetDevice(&curDev));
494	        if (m_key.deviceId() != curDev)
495	        {
496	            throw StreamError("Cannot activate cvcuda.Stream (created on device " + std::to_string(m_key.deviceId())
497	                              + ") while current CUDA device is " + std::to_string(curDev));
498	        }
499	    }
500	    StreamStack::Instance().push(*this);
501	}
502	
503	void Stream::deactivate(py::object, py::object, py::object) const
504	{
505	    ::cvcudapy::NvtxRange nvtxRange("cvcuda.Stream.__exit__");
506	    StreamStack::Instance().pop();
507	}
