683	template<ExternalStreamType E>
684	static void ExportExternalStream(py::module &m)
685	{
686	    m.def("as_stream",
687	          [](ExternalStream<E> extStream)
688	          {
689	              ::cvcudapy::NvtxRange nvtxRange("cvcuda.as_stream");
690	              return std::make_shared<Stream>(extStream);
691	          });
692	}
693	
694	static void LogCleanupWarning(const std::exception &e)
695	{
696	    std::cerr << "Warning CVCUDA cleanup may be incomplete due to: " << e.what() << std::endl;
697	}
698	
699	void Stream::CleanupAtExit(const std::shared_ptr<Stream> &globalStream)
700	{
701	    // No globalStream means no device at module-init time, no streams were ever
702	    // created, nothing to sync. Cleanup is a no-op.
703	    if (!globalStream)
704	    {
705	        return;
706	    }
707	
708	    try
709	    {
710	        for (std::shared_ptr<Stream> stream : Cache::Instance().fetchAll<Stream>())
711	        {
712	            stream->sync();
713	        }
714	        globalStream->sync();
715	        SyncAuxStream();
716	
717	        // There should only be 1 stream in the stack, namely the global stream.
718	        if (auto s = StreamStack::Instance().top(); s != globalStream)
719	        {
720	            std::cerr << "Stream stack leak detected" << std::endl;
721	        }
722	
723	        // Make sure stream stack is empty.
724	        while (auto s = StreamStack::Instance().top())
725	        {
726	            StreamStack::Instance().pop();
727	        }
728	
729	        // Make sure the gc bag is also cleaned up *after* all streams are done,
730	        // when all remaining items that need to be GC'd are in the bag.
731	        ClearGCBag();
732	    }
733	    catch (const py::error_already_set &e)
734	    {
735	        LogCleanupWarning(e);
736	    }
737	    catch (const StreamError &e)
738	    {
739	        LogCleanupWarning(e);
740	    }
741	    catch (const std::invalid_argument &e)
742	    {
743	        LogCleanupWarning(e);
744	    }
745	    catch (const std::domain_error &e)
746	    {
747	        LogCleanupWarning(e);
748	    }
749	    catch (const std::length_error &e)
750	    {
751	        LogCleanupWarning(e);
752	    }
753	    catch (const std::out_of_range &e)
754	    {
755	        LogCleanupWarning(e);
756	    }
757	    catch (const std::range_error &e)
758	    {
759	        LogCleanupWarning(e);
760	    }
761	    catch (const std::overflow_error &e)
762	    {
763	        LogCleanupWarning(e);
764	    }
765	    catch (const std::underflow_error &e)
766	    {
767	        LogCleanupWarning(e);
768	    }
769	    catch (const std::bad_alloc &e)
770	    {
771	        LogCleanupWarning(e);
772	    }
773	}
774	
775	void Stream::Export(py::module &m)
776	{
777	    py::class_<Stream, std::shared_ptr<Stream>, CacheItem> stream(m, "Stream",
778	                                                                  R"pbdoc(
779	        A CUDA stream that cvcuda operators can be submitted to.
780	
781	        Streams created via ``cvcuda.Stream()`` are non-blocking
782	        (``cudaStreamNonBlocking``) so they can run concurrently with CUDA's
783	        legacy default stream and with other non-blocking streams.
784	
785	        Cross-library stream safety is handled automatically via the CUDA
786	        Array Interface (CAI) v3 ``stream`` field:
787	
788	        * On **input**, ``cvcuda.as_tensor`` / ``cvcuda.as_image`` read
789	          ``__cuda_array_interface__["stream"]`` from the producer (cupy,
790	          torch, jax, etc.) and arrange for the first cvcuda operator to
791	          insert the proper ``cudaStreamWaitEvent`` before reading the data.
792	          No user-side ``synchronize()`` call is required.
793	        * On **output**, tensors returned by ``cvcuda.Tensor.cuda()`` /
794	          ``cvcuda.Image.cuda()`` populate ``__cuda_array_interface__
795	          ["stream"]`` with the cvcuda stream the data was last written on,
796	          so downstream consumers can sync themselves.
797	
798	        Advanced usage:
799	
800	        * **Opt out of the implicit wait**: export your buffer with
801	          ``stream: -1`` in its CAI dict to tell cvcuda you've already
802	          synchronized; the first op then runs without an extra event.
803	        * **Legacy default stream**: if your producer uses v2 CAI (no
804	          ``stream`` field) or advertises ``stream: 1``, cvcuda waits on the
805	          legacy default stream.  This is the safe conservative default but
806	          forfeits concurrency with stream-0 work.
807	        * **Use the default stream**: ``cvcuda.Stream.default`` wraps stream
808	          0 and has the usual legacy-default blocking semantics; use it when
809	          you want implicit sync with everything else on stream 0 and don't
810	          need the concurrency of a dedicated stream.
811	        )pbdoc");
812	
813	    stream.def(py::init(&Stream::Create),
814	               "Create a new CUDA stream.  Streams created this way are non-blocking; "
815	               "cross-library synchronization is handled automatically via the CAI "
816	               "``stream`` field (see the class docstring).");
817	
818	    py::module_ internal = m.attr(INTERNAL_SUBMODULE_NAME);
819	    internal.def("syncAuxStream", &SyncAuxStream);
820	
821	    // Wrap the CUDA legacy default stream as `cvcuda.Stream.default` and seed
822	    // the per-thread stream stack so `cvcuda.Stream.current` has something to
823	    // return.
824	    //
825	    // Skipped on hosts with no CUDA device (CPU-only build/CI nodes,
826	    // CUDA_VISIBLE_DEVICES=""): wrapping stream 0 unavoidably touches the
827	    // CUDA runtime (e.g. the `Stream` ctor's cudaStreamGetFlags + aux-stream
828	    // bookkeeping), which fails without a driver-bound device. We also skip
829	    // registering the `current` static property in that case — there is no
830	    // sensible value, and exposing a getter that throws breaks introspection
831	    // tools (pybind11_stubgen, sphinx-autodoc) that walk class members.
832	    int deviceCount = 0;
833	    if (cudaError_t devCntErr = cudaGetDeviceCount(&deviceCount);
834	        devCntErr == cudaErrorNoDevice || devCntErr == cudaErrorStubLibrary)
835	    {
836	        (void)cudaGetLastError();
837	        deviceCount = 0;
838	    }
839	    std::shared_ptr<Stream> globalStream;
840	    if (deviceCount > 0)
841	    {
842	        stream.def_property_readonly_static(
843	            "current", [](py::object) { return Current().sharedStream(); },
844	            "Get the current CUDA stream for this thread.");
845	
846	        static priv::ExternalStream<priv::VOIDP> cudaDefaultStream(static_cast<cudaStream_t>(nullptr));
847	        globalStream = std::make_shared<Stream>(cudaDefaultStream);
848	        StreamStack::Instance().push(*globalStream);
849	        stream.attr("default") = globalStream;
850	    }
851	
852	    // Order from most specific to less specific
853	    ExportExternalStream<TORCH>(m);
854	    ExportExternalStream<CUPY>(m);
855	    ExportExternalStream<VOIDP>(m);
856	    ExportExternalStream<INT>(m);
857	
858	    fflush(stdout);
859	
860	    stream.def("__enter__", &Stream::activate, "Activate the CUDA stream as the current stream for this thread.")
861	        .def("__exit__", &Stream::deactivate, "Deactivate the CUDA stream as the current stream for this thread.")
862	        .def("sync", &Stream::sync, "Wait for all preceding CUDA calls in the current stream to complete.")
863	        .def("wait_stream", &Stream::wait_stream, py::arg("other"),
864	             "Insert a dependency on 'other' into this stream. All subsequent work enqueued on this stream "
865	             "will wait until all work currently enqueued on 'other' has completed. "
866	             "Calling wait_stream(self) is a no-op. "
867	             "Cross-device usage is not supported and will raise a CUDA error.")
868	        .def("__int__", &Stream::pyhandle, "Cast the CUDA stream object to an integer handle.")
869	        .def("__repr__", &util::ToString<Stream>, "Return a string representation of the CUDA stream object.")
870	        .def_property_readonly("handle", &Stream::pyhandle, "Get the integer handle for the CUDA stream object.")
871	        .def_property_readonly("id", &Stream::id, "Get the unique ID for the CUDA stream object.");
872	
873	    // Make sure all streams we've created are synced when script ends.
874	    // Also make cleanup hold the globalStream reference during script execution.
875	    util::RegisterCleanup(m, [globalStream]() { CleanupAtExit(globalStream); });
876	}
877	
878	} // namespace nvcvpy::priv
