Resource::~Resource()
{
    int savedDev = -1;
    util::CheckLog(cudaGetDevice(&savedDev));

    for (const auto &[dev, evt] : m_events)
    {
        util::CheckLog(cudaSetDevice(dev));
        util::CheckLog(cudaEventDestroy(evt));
