cudaEvent_t Resource::event()
{
    int dev;
    util::CheckThrow(cudaGetDevice(&dev));

    auto it = m_events.find(dev);
    if (it == m_events.end())
    {
        cudaEvent_t evt = nullptr;
        util::CheckThrow(cudaEventCreateWithFlags(&evt, cudaEventDisableTiming));
        m_events.emplace(dev, evt);
